def solve(n, p):
    # Initialize the board with -1 indicating no region assigned
    board = [[-1] * n for _ in range(n)]

    # Assign the main diagonal numbers to their respective regions
    for i in range(n):
        board[i][i] = p[i]

    # Function to check if a cell is within the bounds of the board
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n

    # Function to perform a flood fill to assign regions
    def flood_fill(x, y, target, region):
        if not is_valid(x, y) or board[x][y] != target or board[x][y] == -1:
            return
        board[x][y] = region
        flood_fill(x + 1, y, target, region)
        flood_fill(x - 1, y, target, region)
        flood_fill(x, y + 1, target, region)
        flood_fill(x, y - 1, target, region)

    # Assign regions to the rest of the cells
    for i in range(n):
        for j in range(n):
            if board[i][j] == -1:
                flood_fill(i, j, p[i], p[i])

    # Check if the solution is valid
    for i in range(n):
        for j in range(n):
            if board[i][i] != p[i]:
                return -1
            if board[i][j] != p[i] and (i, j) not in [(x, x) for x in range(n)]:
                return -1

    # Output the solution
    for row in board:
        print(' '.join(map(str, row)))
    return 0

